<!-- @FIGURE_UI_BEGIN -->
<label>Sampling interval T<sub>s</sub>: <output id="samplingIntervalVal">1</output><input id="samplingIntervalInput" type="range" min="0.4" max="2" step="0.05" value="1" oninput="document.getElementById('samplingIntervalVal').value=(+this.value).toFixed(2);update_samplingInterval(+this.value)"></label>
