  var p = draw.path(d).fill('none').stroke({ color: GREEN, width: 6, linecap: 'round', linejoin: 'round' });
  p.css('cursor', 'pointer');
  p.on('mousemove', function (e) {
    showTooltip('The common sinc kernel: every sample receives a shifted and scaled copy of this shape.', e);
  }).on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Sinc reconstruction kernel', 'The kernel has value 1 at its center and zero at neighboring sample instants. That zero-crossing pattern lets each reconstructed curve pass exactly through the sample values.');
    });
}

function drawOperators() {
  addText('∗', 465, 213, 70, { family: 'Times New Roman, serif', halo: 5 });
  addText('=', 935, 218, 52, { family: 'Times New Roman, serif', halo: 5 });
}

function drawRightPanel(samples) {
  var x0 = 1010, x1 = 1455, y0 = 248, tMin = -4.4, tMax = 4.4;
  var xScale = (x1 - x0) / (tMax - tMin);
  var yScale = 68;
  function xMap(t) { return x0 + (t - tMin) * xScale; }
  function yMap(y) { return y0 - y * yScale; }

  addArrowAxis(x0, y0, x1, y0, BLACK, 4);
  addText('t', x1 + 7, y0 + 18, 39, { italic: true, halo: 3 });

  var drawUpTo = (buildCount == null) ? samples.length : buildCount;
  var copiesToDraw = [];
  if (copyView !== 'Hide copies') {
    if (copyView === 'Show selected copy') {
      for (var si = 0; si < samples.length; si++) {
        if (samples[si].n === selectedN) copiesToDraw.push(samples[si]);
      }
    } else {
      copiesToDraw = samples.slice(0, drawUpTo);
    }
  }

  for (var c = 0; c < copiesToDraw.length; c++) {
    var s = copiesToDraw[c];
    if (s.t < tMin - 2.5 * samplingInterval || s.t > tMax + 2.5 * samplingInterval) continue;
    var dCopy = pathFor(function (t) {
      return s.y * sinc((t - s.t) / samplingInterval);
    }, tMin, tMax, 250, xMap, yMap);
    var cp = draw.path(dCopy).fill('none')
      .stroke({ color: GREEN, width: (s.n === selectedN ? 4.2 : 3), dasharray: '11 9', linecap: 'round', linejoin: 'round' })
      .opacity(s.n === selectedN ? 0.95 : 0.75);
    cp.css('cursor', 'pointer');
    (function (ss) {
      cp.on('mousemove', function (e) {
        showTooltip('Dashed sinc copy from sample n = ' + ss.n + ', scaled by height ' + ss.y.toFixed(2) + '.', e);
      }).on('mouseleave', function () { hideTooltip(); });
    })(s);
  }

  var redCount = (buildCount == null) ? samples.length : buildCount;
  var dRed = pathFor(function (t) { return reconAt(t, samples, redCount); }, tMin, tMax, 520, xMap, yMap);
  var red = draw.path(dRed).fill('none')
    .stroke({ color: RED, width: 5.5, linecap: 'round', linejoin: 'round' });
  red.css('cursor', 'pointer');
  red.on('mousemove', function (e) {
    showTooltip('The red signal is the sum of the visible sinc contributions.', e);
  }).on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Linear superposition', 'The red curve is computed by adding the green sinc copies point by point. At sample instants, all other sinc copies are zero, so the red curve passes through the blue sample value.');
    });

  var vis = visibleSamples(samples);
  for (var i = 0; i < vis.length; i++) {
    addImpulse(xMap(vis[i].t), y0, vis[i].y, yScale, { color: BLUE, interactive: true, n: vis[i].n });
  }
}

function render() {
  draw.clear();
  lastSamples = sampleList(samplingInterval);
  if (!lastSamples.some(function (s) { return s.n === selectedN; })) selectedN = 0;
  drawLeftPanel(lastSamples);
  drawOperators();
  drawMiddlePanel();
  drawRightPanel(lastSamples);
}

function stopAnimation() {
  if (animTimer) {
    clearInterval(animTimer);
    animTimer = null;
  }
}

function update_samplingInterval(v) {
  samplingInterval = v;
  buildCount = null;
  stopAnimation();
  render();
}

function toggle_sincCopyView(v) {
  copyView = (typeof v === 'string') ? v : (v ? 'Show all copies' : 'Hide copies');
  if (copyView === 'Show selected copy' && selectedN == null) selectedN = 0;
  buildCount = null;
  stopAnimation();
  render();
}

function trigger_convolutionBuild() {
  stopAnimation();
  copyView = 'Show all copies';
  var sel = document.getElementById('sincCopyViewInput');
  if (sel) sel.value = copyView;
  var samples = sampleList(samplingInterval);
  buildCount = 0;
  render();
  animTimer = setInterval(function () {
    buildCount += 1;
    render();
    if (buildCount >= samples.length) {
      stopAnimation();
      setTimeout(function () {
        buildCount = null;
        render();
      }, 350);
    }
  }, 230);
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[currentStep];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + steps.length + ' · ' + st.title;
  if (st.state.samplingInterval != null) {
    samplingInterval = st.state.samplingInterval;
    document.getElementById('samplingIntervalInput').value = samplingInterval;
    document.getElementById('samplingIntervalVal').value = samplingInterval.toFixed(2).replace(/\.00$/, '');
  }
  if (st.state.sincCopyView) {
    copyView = st.state.sincCopyView;
    document.getElementById('sincCopyViewInput').value = copyView;
  }
  stopAnimation();
  buildCount = null;
  selectedN = 0;
  render();
  if (currentStep === 2) {
    setTimeout(function () { trigger_convolutionBuild(); }, 250);
  }
}

function nextStep() {
  applyStep((currentStep + 1) % steps.length);
}

function prevStep() {
  applyStep((currentStep + steps.length - 1) % steps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Ideal reconstruction turns discrete samples back into a continuous signal by summing shifted, scaled sinc kernels, one kernel copy per sample.
KEY INSIGHT (what students should walk away understanding): Sinc interpolation works because every sample contributes a shifted, scaled copy of the same kernel, and the continuous reconstruction is the linear sum of all those copies.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Ideal reconstruction turns discrete samples back into a continuous signal by summing shifted, scaled sinc kernels, one kernel copy per sample.",
  "figureType": "diagram",
  "elements": [
    "left panel horizontal time axis labeled t with arrowhead",
    "left panel discrete sample sequence shown as blue vertical impulse arrows at regularly spaced sample times",
    "left panel time labels -T_s, 0, T_s, and 2T_s under selected impulse positions",
    "left panel additional unlabeled blue sample impulses before and after the labeled samples, including positive and negative sample values",
    "convolution operator symbol between the left and middle panels",
    "middle panel horizontal time axis labeled t with arrowhead",
    "middle panel vertical amplitude axis with arrowhead",
    "middle panel amplitude label 1 beside the vertical axis",
    "middle panel green sinc-like reconstruction kernel centered at t = 0 with peak value 1 and decaying oscillatory sidelobes",
    "equals sign between the middle and right panels",
    "right panel horizontal time axis labeled t with arrowhead",
    "right panel blue vertical impulse arrows at sample positions",
    "right panel dashed green shifted and scaled sinc copies, one centered at each sample position and scaled by that sample value",
    "right panel solid red reconstructed continuous signal formed by summing all dashed green sinc copies",
    "right panel visible interpolation points where the red curve passes through the blue sample values"
  ],
  "interactions": [
    {
      "id": "samplingInterval",
      "type": "slider",
      "label": "Sampling interval T_s",
      "range": [
        0.4,
        2,
        0.05
      ],
      "default": 1,
      "teaches": "Changing the spacing between samples shows why dense samples allow the sinc copies to combine into a faithful red reconstruction, while samples spaced too far apart make the copies interfere and produce aliasing distortion"
    },
    {
      "id": "sincCopyView",
      "type": "toggle",
      "label": "Sinc copy visibility",
      "options": [
        "Show all copies",
        "Show selected copy",
        "Hide copies"
      ],
      "default": "Show all copies",
      "teaches": "The red curve is not drawn independently; it is the sum of many shifted, scaled green sinc copies, and hiding or isolating those copies makes the superposition visible"
    },
    {
      "id": "selectContribution",
      "type": "click",
      "teaches": "Clicking a sample focuses attention on the single sinc copy generated by that sample, making clear that sample height controls the copy's vertical scale and sample time controls its horizontal shift"
    },
    {
      "id": "convolutionBuild",
      "type": "animation",
      "label": "Animate convolution sweep",
      "loop": false,
      "teaches": "Reconstruction is built incrementally: each sample contributes one scaled kernel, and the cumulative sum approaches the final red continuous signal as more samples are added"
    }
  ],
  "demo_steps": [
    {
      "title": "Samples, kernel, and reconstruction",
      "narration": "The left panel shows discrete sample values, the middle panel shows the sinc reconstruction kernel, and the right panel shows the result of convolving them. Each blue sample in the right panel creates one dashed green sinc copy.",
      "state": {
        "samplingInterval": 1,
        "sincCopyView": "Show all copies"
      }
    },
    {
      "title": "Isolate one sample's contribution",
      "narration": "Switch to a selected copy view and click a blue sample. The corresponding green sinc is centered at that sample time and scaled to that sample height.",
      "state": {
        "samplingInterval": 1,
        "sincCopyView": "Show selected copy"
      }
    },
    {
      "title": "Build the sum",
      "narration": "Run the convolution sweep to add the shifted sinc copies one by one. The red curve emerges as the cumulative sum of all the individual green contributions.",
      "state": {
        "samplingInterval": 1,
        "sincCopyView": "Show all copies"
      }
    },
    {
      "title": "Change the sampling interval",
      "narration": "Decrease T_s to make the reconstruction stable and faithful; increase T_s past the Nyquist limit to see the sinc copies overlap incorrectly and bend the red envelope into an aliased signal.",
      "state": {
        "samplingInterval": 1.6,
        "sincCopyView": "Show all copies"
      }
    }
  ],
  "keyInsight": "Sinc interpolation works because every sample contributes a shifted, scaled copy of the same kernel, and the continuous reconstruction is the linear sum of all those copies.",
  "reconstructionNotes": "Use a wide three-part equation layout: sample impulse train on the left, green sinc kernel in the middle, and reconstructed signal on the right. Keep axes black with large arrowheads and italic t labels. Draw sample impulses in bright blue with triangular arrowheads. Draw the kernel and individual shifted copies in bright green, using dashed strokes for the right-panel copies and a solid stroke for the middle-panel kernel. Draw the final reconstructed signal as a thick red smooth curve passing through the tops of the blue sample arrows. The right panel should clearly show many overlapping green dashed sinc copies whose sum forms the red curve. As T_s increases, space the blue impulses farther apart and visibly distort the red reconstruction to communicate aliasing; as T_s decreases, make the red curve smoother and closer to the intended continuous envelope."
}

