Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Sampling interval T<sub>s</sub>: <output id="samplingIntervalVal">1</output><input id="samplingIntervalInput" type="range" min="0.4" max="2" step="0.05" value="1" oninput="document.getElementById('samplingIntervalVal').value=(+this.value).toFixed(2).replace(/\.00$/,'');update_samplingInterval(+this.value)"></label>
<label>Sinc copy visibility <select id="sincCopyViewInput" onchange="toggle_sincCopyView(this.value)"><option selected>Show all copies</option><option>Show selected copy</option><option>Hide copies</option></select></label>
<button onclick="trigger_convolutionBuild()">Animate convolution sweep</button>
<span style="font-size:10px;color:#444">Click a blue sample in the right panel to isolate its shifted, scaled sinc copy.</span>
<span id="demoNarration" style="display:block;margin:0;font-size:10px;max-width:180px">The left panel shows discrete sample values, the middle panel shows the sinc reconstruction kernel, and the right panel shows the result of convolving them. Each blue sample in the right panel creates one dashed green sinc copy.</span>
<span style="display:flex;gap:4px;align-items:center"><button onclick="prevStep()">◀</button><span id="stepLabel"></span><button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 2400, H = 500;
draw.viewbox(0, 0, W, H);

var BLUE = '#2448ff';
var GREEN = '#50ee00';
var RED = '#ff0a00';
var BLACK = '#15191a';

var samplingInterval = 1;
var copyView = 'Show all copies';
var selectedN = 1;
var buildCount = null;
var animTimer = null;
var currentStep = 0;
var lastSamples = [];

var baseSampleValues = {
  '-5': 0.08,
  '-4': 0.30,
  '-3': 0.38,
  '-2': 0.28,
  '-1': 0.35,
  '0': 1.55,
  '1': 3.35,
  '2': 2.85,
  '3': 1.24,
  '4': -0.54,
  '5': -0.58,
  '6': 0.30,
  '7': 1.63,
  '8': 0.10
};

var steps = [
  {
    title: 'Samples, kernel, and reconstruction',
    narration: 'The left panel shows discrete sample values, the middle panel shows the sinc reconstruction kernel, and the right panel shows the result of convolving them. Each blue sample in the right panel creates one dashed green sinc copy.',
    state: { samplingInterval: 1, sincCopyView: 'Show all copies' }
  },
  {
    title: "Isolate one sample's contribution",
    narration: 'Switch to a selected copy view and click a blue sample. The corresponding green sinc is centered at that sample time and scaled to that sample height.',
    state: { samplingInterval: 1, sincCopyView: 'Show selected copy' }
  },
  {
    title: 'Build the sum',
    narration: 'Run the convolution sweep to add the shifted sinc copies one by one. The red curve emerges as the cumulative sum of all the individual green contributions.',
    state: { samplingInterval: 1, sincCopyView: 'Show all copies' }
  },
  {
    title: 'Change the sampling interval',
    narration: 'Decrease T_s to make the reconstruction stable and faithful; increase T_s past the Nyquist limit to see the sinc copies overlap incorrectly and bend the red envelope into an aliased signal.',
    state: { samplingInterval: 1.6, sincCopyView: 'Show all copies' }
  }
];

function sinc(z) {
  if (Math.abs(z) < 1e-8) return 1;
  return Math.sin(Math.PI * z) / (Math.PI * z);
}

function signal(t) {
  var total = 0;
  for (var k in baseSampleValues) {
    if (Object.prototype.hasOwnProperty.call(baseSampleValues, k)) {
      total += baseSampleValues[k] * sinc(t - (+k));
    }
  }
  return total;
}

function sampleList(Ts) {
  var tMin = -5.3, tMax = 8.2;
  var out = [];
  var n0 = Math.ceil((tMin - 2 * Ts) / Ts);
  var n1 = Math.floor((tMax + 2 * Ts) / Ts);
  for (var n = n0; n <= n1; n++) {
    var t = n * Ts;
    out.push({ n: n, t: t, y: signal(t) });
  }
  return out;
}

function visibleSamples(samples, a, b) {
  return samples.filter(function (s) { return s.t >= a && s.t <= b; });
}

function reconAt(t, samples, count) {
  var total = 0;
  var lim = (count == null) ? samples.length : Math.max(0, Math.min(count, samples.length));
  for (var i = 0; i < lim; i++) {
    total += samples[i].y * sinc((t - samples[i].t) / samplingInterval);
  }
  return total;
}

function addArrowAxis(x1, y1, x2, y2, color, width) {
  color = color || BLACK;
  width = width || 6;
  draw.line(x1, y1, x2 - 34, y2).stroke({ color: color, width: width, linecap: 'butt' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var len = 48, wid = 34;
  var bx = x2 - len * Math.cos(ang);
  var by = y2 - len * Math.sin(ang);
  var px = wid * Math.sin(ang) / 2;
  var py = -wid * Math.cos(ang) / 2;
  draw.polygon([[x2, y2], [bx + px, by + py], [bx - px, by - py]])
    .fill(color).stroke('none');
}

function addVerticalAxis(x, yBottom, yTop, color, width) {
  color = color || BLACK;
  width = width || 7;
  draw.line(x, yBottom, x, yTop + 36).stroke({ color: color, width: width });
  draw.polygon([[x, yTop], [x - 25, yTop + 58], [x + 25, yTop + 58]])
    .fill(color).stroke('none');
}

function addImpulse(x, y0, amp, yScale, opts) {
  opts = opts || {};
  var color = opts.color || BLUE;
  var interactive = opts.interactive;
  var n = opts.n;
  var tipY = y0 - amp * yScale;
  var minLen = 28;
  if (Math.abs(tipY - y0) < minLen) tipY = y0 - (amp >= 0 ? minLen : -minLen);

  var g = draw.group();
  var pos = tipY < y0;
  var head = opts.head || 26;
  var half = opts.half || 14;
  var stemW = opts.stemW || 6;

  if (pos) {
    g.line(x, y0, x, tipY + head).stroke({ color: color, width: stemW, linecap: 'butt' });
    g.polygon([[x, tipY], [x - half, tipY + head], [x + half, tipY + head]]).fill(color).stroke('none');
  } else {
    g.line(x, y0, x, tipY - head).stroke({ color: color, width: stemW, linecap: 'butt' });
    g.polygon([[x, tipY], [x - half, tipY - head], [x + half, tipY - head]]).fill(color).stroke('none');
  }

  if (interactive) {
    g.circle(16).center(x, tipY).fill(BLUE).opacity(0.96);
    g.line(x, Math.min(y0, tipY) - 10, x, Math.max(y0, tipY) + 10)
      .stroke({ color: '#ffffff', width: 28, opacity: 0.001 });
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) {
      showTooltip('Sample at t = ' + (n * samplingInterval).toFixed(2) + ' creates one shifted, scaled sinc copy.', e);
    }).on('mouseleave', function () {
      hideTooltip();
    }).on('click', function () {
      selectedN = n;
      copyView = 'Show selected copy';
      var sel = document.getElementById('sincCopyViewInput');
      if (sel) sel.value = copyView;
      buildCount = null;
      stopAnimation();
      render();
      showPopup(
        'One sample, one sinc copy',
        'This blue impulse fixes the center and height of one green dashed sinc. The red reconstruction is the point-by-point sum of this contribution plus every other sample contribution.'
      );
    });
  } else {
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) {
      showTooltip('Discrete sample value', e);
    }).on('mouseleave', function () { hideTooltip(); });
  }
  return g;
}

function addText(txt, x, y, size, opts) {
  opts = opts || {};
  var t = draw.text(txt).move(x, y);
  t.font({
    family: opts.family || 'Times New Roman, serif',
    size: size,
    style: opts.italic ? 'italic' : 'normal',
    weight: opts.weight || 'normal'
  }).fill(opts.fill || BLACK);
  if (opts.halo) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opts.halo, 'stroke-linejoin': 'round' });
  }
  return t;
}

function addCenteredText(txt, cx, y, size, opts) {
  var t = addText(txt, 0, y, size, opts);
  try { t.cx(cx); } catch (e) { t.move(cx - 20, y); }
  return t;
}

function pathFor(fn, a, b, steps, xMap, yMap) {
  var d = '';
  for (var i = 0; i <= steps; i++) {
    var t = a + (b - a) * i / steps;
    var y = fn(t);
    if (!isFinite(y)) continue;
    d += (d ? 'L' : 'M') + xMap(t).toFixed(2) + ',' + yMap(y).toFixed(2);
  }
  return d;
}

function drawLeftPanel(samples) {
  var x0 = 70, x1 = 835, y0 = 294, center = 405, xScale = 82, yScale = 72;
  addArrowAxis(x0, y0, x1, y0, BLACK, 6);
  addText('t', x1 + 12, y0 + 19, 54, { italic: true, halo: 4 });

  var shown = samples.filter(function (s) { return s.t >= -4.05 && s.t <= 6.25; });
  for (var i = 0; i < shown.length; i++) {
    var x = center + shown[i].t * xScale;
    if (x > x0 + 16 && x < x1 - 26) {
      addImpulse(x, y0, shown[i].y, yScale, { color: BLUE, stemW: 7, head: 27, half: 15 });
    }
  }

  [
    { t: -samplingInterval, label: '-Tₛ', dx: -3 },
    { t: 0, label: '0', dx: 0 },
    { t: samplingInterval, label: 'Tₛ', dx: 3 },
    { t: 2 * samplingInterval, label: '2Tₛ', dx: 11 }
  ].forEach(function (m) {
    var x = center + m.t * xScale;
    if (x > x0 && x < x1 - 22) {
      addCenteredText(m.label, x + m.dx, y0 + 28, 47, { italic: true, halo: 5 });
    }
  });
}

function drawMiddlePanel() {
  var x0 = 948, x1 = 1548, y0 = 294, xc = 1245, yScale = 108, xScale = 69;
  addArrowAxis(x0, y0, x1, y0, BLACK, 6);
  addVerticalAxis(xc, 370, 20, BLACK, 7);
  addText('t', x1 + 11, y0 + 20, 54, { italic: true, halo: 4 });
  addText('1', xc - 50, y0 - yScale - 36, 53, { halo: 5 });

  var d = pathFor(function (t) { return sinc(t / samplingInterval); }, -4.45, 4.45, 560,
    function (t) { return xc + t * xScale; },
    function (y) { return y0 - y * yScale; });
  var p = draw.path(d).fill('none').stroke({ color: GREEN, width: 8, linecap: 'round', linejoin: 'round' });
  p.css('cursor', 'pointer');
  p.on('mousemove', function (e) {
    showTooltip('The common sinc kernel: every sample receives a shifted and scaled copy of this same shape.', e);
  }).on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Sinc reconstruction kernel', 'The sinc kernel is 1 at its center and zero at neighboring sample instants. That zero-crossing pattern lets the summed reconstruction pass exactly through the sample values.');
    });
}

function drawOperators() {
  addText('∗', 872, 250, 78, { family: 'Times New Roman, serif', halo: 6 });
  addText('=', 1590, 252, 67, { family: 'Times New Roman, serif', halo: 6 });
}

function drawRightPanel(samples) {
  var x0 = 1695, x1 = 2350, y0 = 294, tMin = -4.1, tMax = 7.45;
  var xScale = (x1 - x0) / (tMax - tMin);
  var yScale = 71;

  function xMap(t) { return x0 + (t - tMin) * xScale; }
  function yMap(y) { return y0 - y * yScale; }

  addArrowAxis(x0, y0, x1, y0, BLACK, 6);
  addText('t', x1 + 10, y0 + 20, 54, { italic: true, halo: 4 });

  var drawUpTo = (buildCount == null) ? samples.length : buildCount;
  var copiesToDraw = [];
  if (copyView !== 'Hide copies') {
    if (copyView === 'Show selected copy') {
      for (var si = 0; si < samples.length; si++) {
        if (samples[si].n === selectedN) copiesToDraw.push(samples[si]);
      }
    } else {
      copiesToDraw = samples.slice(0, drawUpTo);
    }
  }

  for (var c = 0; c < copiesToDraw.length; c++) {
    var s = copiesToDraw[c];
    if (s.t < tMin - 2.8 * samplingInterval || s.t > tMax + 2.8 * samplingInterval) continue;
    var dCopy = pathFor(function (t) {
      return s.y * sinc((t - s.t) / samplingInterval);
    }, tMin, tMax, 390, xMap, yMap);
    var cp = draw.path(dCopy).fill('none')
      .stroke({ color: GREEN, width: (s.n === selectedN ? 5.4 : 4.2), dasharray: '18 13', linecap: 'round', linejoin: 'round' })
      .opacity(s.n === selectedN ? 1 : 0.88);
    cp.css('cursor', 'pointer');
    (function (ss) {
      cp.on('mousemove', function (e) {
        showTooltip('Dashed sinc copy from sample n = ' + ss.n + ', scaled by height ' + ss.y.toFixed(2) + '.', e);
      }).on('mouseleave', function () { hideTooltip(); });
    })(s);
  }

  var redCount = (buildCount == null) ? samples.length : buildCount;
  var dRed = pathFor(function (t) { return reconAt(t, samples, redCount); }, tMin, tMax, 760, xMap, yMap);
  var red = draw.path(dRed).fill('none')
    .stroke({ color: RED, width: 8.5, linecap: 'round', linejoin: 'round' });
  red.css('cursor', 'pointer');
  red.on('mousemove', function (e) {
    showTooltip('The red signal is the linear sum of the shifted, scaled sinc copies.', e);
  }).on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Linear superposition', 'The red curve is computed by adding the green sinc copies point by point. At sample instants, every other ideal sinc copy is zero, so the red curve passes through the blue sample value.');
    });

  var vis = visibleSamples(samples, tMin, tMax);
  for (var i = 0; i < vis.length; i++) {
    addImpulse(xMap(vis[i].t), y0, vis[i].y, yScale, { color: BLUE, interactive: true, n: vis[i].n, stemW: 6.5, head: 27, half: 15 });
  }
}

function render() {
  draw.clear();
  lastSamples = sampleList(samplingInterval);
  if (!lastSamples.some(function (s) { return s.n === selectedN; })) selectedN = Math.round(1 / samplingInterval);
  drawLeftPanel(lastSamples);
  drawOperators();
  drawMiddlePanel();
  drawRightPanel(lastSamples);
}

function stopAnimation() {
  if (animTimer) {
    clearInterval(animTimer);
    animTimer = null;
  }
}

function update_samplingInterval(v) {
  samplingInterval = v;
  buildCount = null;
  stopAnimation();
  render();
}

function toggle_sincCopyView(v) {
  copyView = (typeof v === 'string') ? v : (v ? 'Show all copies' : 'Hide copies');
  if (copyView === 'Show selected copy' && selectedN == null) selectedN = 1;
  buildCount = null;
  stopAnimation();
  render();
}

function trigger_convolutionBuild() {
  stopAnimation();
  copyView = 'Show all copies';
  var sel = document.getElementById('sincCopyViewInput');
  if (sel) sel.value = copyView;
  var samples = sampleList(samplingInterval);
  buildCount = 0;
  render();
  animTimer = setInterval(function () {
    buildCount += 1;
    render();
    if (buildCount >= samples.length) {
      stopAnimation();
      setTimeout(function () {
        buildCount = null;
        render();
      }, 360);
    }
  }, 210);
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[currentStep];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + steps.length + ' · ' + st.title;

  if (st.state.samplingInterval != null) {
    samplingInterval = st.state.samplingInterval;
    document.getElementById('samplingIntervalInput').value = samplingInterval;
    document.getElementById('samplingIntervalVal').value = String(samplingInterval).replace(/\.00$/, '');
  }
  if (st.state.sincCopyView) {
    copyView = st.state.sincCopyView;
    document.getElementById('sincCopyViewInput').value = copyView;
  }

  stopAnimation();
  buildCount = null;
  selectedN = 1;
  render();

  if (currentStep === 2) {
    setTimeout(function () { trigger_convolutionBuild(); }, 260);
  }
}

function nextStep() {
  applyStep((currentStep + 1) % steps.length);
}

function prevStep() {
  applyStep((currentStep + steps.length - 1) % steps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

